import React, { useEffect, useState } from "react";
import { useDispatch, useSelector } from "react-redux";
import { fetchJobs } from "../Features/JobSlice";
import axios from "axios";
import "../Styles/CompanyJobs.css";

const CompanyJobs = () => {
  const dispatch = useDispatch();
  const { jobs } = useSelector((state) => state.jobs);
  const [editingJob, setEditingJob] = useState(null);
  const [editedData, setEditedData] = useState({});
  const companyEmail = JSON.parse(localStorage.getItem("loggedUser"))?.email;

  // Load all jobs from MongoDB
  useEffect(() => {
    dispatch(fetchJobs());
  }, [dispatch]);

  // Filter jobs for current company only
  const companyJobs = jobs.filter((job) => job.organization === companyEmail);

  // Delete a job from MongoDB
  const handleDelete = async (id) => {
    try {
      await axios.delete(`http://localhost:3001/jobs/${id}`);
      alert("Job deleted successfully");
      dispatch(fetchJobs()); // reload after delete
    } catch (err) {
      alert("Failed to delete job");
    }
  };

  // Save job edits
  const handleSave = async () => {
    try {
      await axios.put(
        `http://localhost:3001/jobs/${editingJob._id}`,
        editedData
      );
      alert("Job updated");
      setEditingJob(null);
      dispatch(fetchJobs());
    } catch {
      alert("Update failed");
    }
  };

  return (
    <div className="companyjobs-page">
      <h1 className="companyjobs-title">
        My <span className="accent">Posted Jobs</span>
      </h1>

      {companyJobs.length === 0 ? (
        <p className="no-jobs">No jobs posted yet.</p>
      ) : (
        companyJobs.map((job) => (
          <div key={job._id} className="job-card">
            {editingJob?._id === job._id ? (
              <>
                <input
                  type="text"
                  value={editedData.jobTitle}
                  onChange={(e) =>
                    setEditedData({ ...editedData, jobTitle: e.target.value })
                  }
                />
                <textarea
                  value={editedData.description}
                  onChange={(e) =>
                    setEditedData({
                      ...editedData,
                      description: e.target.value,
                    })
                  }
                />
                <div className="edit-buttons">
                  <button onClick={handleSave}>Save</button>
                  <button onClick={() => setEditingJob(null)}>Cancel</button>
                </div>
              </>
            ) : (
              <>
                <div className="job-header">
                  <h3>{job.jobTitle}</h3>
                  <span className="rate">
                    {job.rate} OMR · {job.rateType}
                  </span>
                </div>
                <p className="desc">{job.description}</p>
                <div className="job-actions">
                  <button
                    className="btn-edit"
                    onClick={() => {
                      setEditingJob(job);
                      setEditedData(job);
                    }}
                  >
                    Edit
                  </button>
                  <button
                    className="btn-delete"
                    onClick={() => handleDelete(job._id)}
                  >
                    Delete
                  </button>
                </div>
              </>
            )}
          </div>
        ))
      )}
    </div>
  );
};

export default CompanyJobs;
